  if (!index.has_value()) {
    decision.message =
        "dynamic_unlock skipped: lastNodeId '" + confirmed_last_node_id +
        "' (sequence " + std::to_string(confirmed_last_node_sequence_id) +
        ") does not match any node/sequence of the dispatched order; retain ALL locks. "

